CREATE TABLE ai_provider_configs (id binary(16) PRIMARY KEY, user_id binary(16) NOT NULL, provider varchar(32) NOT NULL, model varchar(80) NOT NULL, thinking_mode varchar(16) NOT NULL, credential_id binary(16) NOT NULL, masked_key varchar(40) NOT NULL, enabled int NOT NULL DEFAULT 1, tested_at datetime(6), created_at datetime(6) NOT NULL, updated_at datetime(6) NOT NULL, UNIQUE KEY ai_provider_configs_user_uq (user_id), FOREIGN KEY (user_id) REFERENCES users(id), FOREIGN KEY (credential_id) REFERENCES credential_refs(id));
